class MeineListe {
   private Knoten anfang; 

   boolean add(DatenElement daten) {
      if(anfang == null) {
         anfang = new Knoten(daten); 
      } else {
         anfang.add(daten);
      }
      return true; 
   }

   boolean entfernen(DatenElement daten) {
      if(anfang != null) {
      // Liste nicht leer
         if(anfang.getDaten() == daten) {
         // betreffender Knoten ist Anfang 
            anfang = anfang.getNachfolger();
            return true; 
         } else {
         //Rekursion
            return anfang.entfernen(daten) != null; 
         }
      } else {
      //Leere Liste
         return false;
      }
   }

   int länge() {
      if(anfang == null) {
      //leere Liste
         return 0; 
      } else {
      //Rekursion
         return anfang.länge(); 
      }
   }

   Knoten getAnfang() {
      return anfang;
   }

   void setAnfang(Knoten anfang) {
      this.anfang = anfang;
   } 
}

class Knoten {
   private Knoten nachfolger;
   private DatenElement daten; 

   Knoten(DatenElement daten) {
      this.daten = daten; 
   }

   Knoten getNachfolger() {
      return nachfolger;
   }

   void setNachfolger(Knoten nachfolger) {
      this.nachfolger = nachfolger;
   }

   DatenElement getDaten() {
      return daten;
   }

   void setDaten(DatenElement daten) {
      this.daten = daten;
   }

   boolean add(DatenElement daten) {
      if(nachfolger == null) {
         nachfolger = new Knoten(daten);
         return true;
      } else {
         return nachfolger.add(daten); // Selbstaufruf --> Rekursion
      }
   } 

   Knoten entfernen(DatenElement daten) {
      if(this.daten == daten) {
      // ich habe die Daten
         return nachfolger; 
      } else {
         if(nachfolger != null) {
         // Nachfolger vorhanden, rekursion
            nachfolger = nachfolger.entfernen(daten); 
            return this; 
         } else {
         // kein Nachfolger -> Abbruch
            return null; 
         }
      }
   }

int länge() {
   if(nachfolger == null) {
      // Ende der Liste
      return 1; 
   } else {
      // Rekursion
      return nachfolger.länge() + 1; 
   }
}

}

class Taxi implements DatenElement {

   int autonummer;
   String farbe; 

   public String toString() {
      return "Autonummer: " + autonummer + "; Farbe: " + farbe; 
   }
}

class Patient implements DatenElement {
   String name;
   String adresse;
   String krankheit;
   int alter;

   public String toString() {
      return "Name: " + name + "; Adresse: " + adresse + "; Krankheit: " + krankheit + "; Alter: " + alter + ";"; 
   }
}
